global_custom_code.loader_start:
static uint32_t g_profileDomain;

static const char* g_profileFunctionList[] = {
    "cuptiCheckpointFree",
    "cuptiCheckpointRestore",
    "cuptiCheckpointSave",
};

enum checkpointProfileCallbackId {
    checkpoint_TRACE_CBID_cuptiCheckpointFree = 0,
    checkpoint_TRACE_CBID_cuptiCheckpointRestore = 1,
    checkpoint_TRACE_CBID_cuptiCheckpointSave = 2,
};

typedef uint32_t (*checkpointRegisterProfileDomain)(const char* domain_name, const char** function_list, uint32_t function_number);
typedef uint8_t (*checkpointIsProfileCallbackEnabled)(uint32_t domain, uint32_t callback_id);
typedef void (*checkpointProfileCallbackBegin)(uint32_t domain, uint32_t callback_id);
typedef void (*checkpointProfileCallbackEnd)(uint32_t domain, uint32_t callback_id);

struct checkpointProfileHandler {
    checkpointRegisterProfileDomain registerProfileDomain;
    checkpointIsProfileCallbackEnabled isCallbackEnabled;
    checkpointProfileCallbackBegin profileCallbackBegin;
    checkpointProfileCallbackEnd profileCallbackEnd;
};

static checkpointProfileHandler g_profileHandler;
static bool gDirectReturn = false;
static const char* gLibName = "checkpoint";

static void InitializeProfileHandler() {
    // get library patch
    const char* profile_tool_library = getenv("WRAPPER_INJECTION_PATH");
    if (profile_tool_library == NULL) {
        return;
    }

    // open profile library
    void* tool_handler = dlopen(profile_tool_library, RTLD_LAZY);
    if (!tool_handler) {
        printf("cannot open the file:%s  with error %s\n", profile_tool_library, dlerror());
        return;
    }

    // init profile handler
    g_profileHandler.registerProfileDomain = reinterpret_cast<checkpointRegisterProfileDomain>(dlsym(tool_handler, "wrapperRegisterProfileDomain"));
    g_profileHandler.isCallbackEnabled = reinterpret_cast<checkpointIsProfileCallbackEnabled>(dlsym(tool_handler, "wrapperIsProfileCallbackEnabled"));
    g_profileHandler.profileCallbackBegin = reinterpret_cast<checkpointProfileCallbackBegin>(dlsym(tool_handler, "wrapperProfileCallbackBegin"));
    g_profileHandler.profileCallbackEnd = reinterpret_cast<checkpointProfileCallbackEnd>(dlsym(tool_handler, "wrapperProfileCallbackEnd"));

    // register profile domain
    if (g_profileHandler.registerProfileDomain != NULL) {
        g_profileDomain = g_profileHandler.registerProfileDomain(gLibName, g_profileFunctionList, sizeof(g_profileFunctionList) / sizeof(g_profileFunctionList[0]));
        if (g_profileDomain == 0) {
            g_profileHandler.isCallbackEnabled = NULL;
        }
    }
}

global_custom_code.pre_wrapper_call:
bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
    g_profileHandler.isCallbackEnabled(g_profileDomain, checkpoint_TRACE_CBID_$WRAPPER_FUNC_NAME) != 0;
if (needProfile) {
    g_profileHandler.profileCallbackBegin(g_profileDomain, checkpoint_TRACE_CBID_$WRAPPER_FUNC_NAME);
}
